export const wikidataUrl = (item) => "https://www.wikidata.org/wiki/" + item;

/** A film as a list carries it: title, year, anything the list adds, its place in a series, and its id. */
export function listed(id, extra = {}) {
  const f = FILM_TABLE[id];
  if (!f) throw new Error("No such film in js/data/films.js: " + id);
  return { t: f.t, y: f.y, ...extra, ...(f.tri ? { tri: f.tri, ord: f.ord } : {}), id };
}
